#include <iostream>
#include <vector>
#include <string>
int main() {
  std::vector<int> v1 = {1, 2, 3};
  std::vector<std::string> v2 = {"hello", "world"};
  // Correct list initialization; type deduction works well
  std::vector<int> v3 {10, 20, 30};
  //This will lead to a compilation error if we attempt to assign a different type, e.g.:
  //std::vector<int> v4 = {1.1, 2.2, 3.3}; // Error: narrowing conversion
  std::vector<double> v5 = {1.1, 2.2, 3.3}; //This works fine
  return 0;
}
